using System.ComponentModel.DataAnnotations;using System.ComponentModel.DataAnnotations.Schema;namespace MiniErp.Models;public class Invoice{public int Id{get;set;}public InvoiceType Type{get;set;}[Required,StringLength(10)]public string Series{get;set;}="A";[Required,StringLength(30)]public string Number{get;set;}="";public DateTime IssueDate{get;set;}=DateTime.Today;public DateTime DueDate{get;set;}=DateTime.Today.AddDays(30);public InvoiceStatus Status{get;set;}public int? SalesOrderId{get;set;}public SalesOrder? SalesOrder{get;set;}public int? PurchaseOrderId{get;set;}public PurchaseOrder? PurchaseOrder{get;set;}public decimal TaxBase{get;set;}[Range(typeof(decimal),"0","100",ParseLimitsInInvariantCulture=true)]public decimal TaxRate{get;set;}=21;public decimal TaxAmount{get;set;}public decimal Total{get;set;}public ICollection<Payment> Payments{get;set;}=[];[NotMapped]public decimal PaidAmount=>Payments.Sum(x=>x.Amount);[NotMapped]public decimal Outstanding=>Total-PaidAmount;}